<tr data-quotation-line>
    <td><input type="hidden" name="lines[<?= salesEscape($lineKey) ?>][line_id]" value="<?= (int)($line['id']??$line['line_id']??0) ?>" data-line-id><input type="hidden" data-line-commission-unit value="<?= salesEscape($line['commission_unit_amount']??'') ?>"><select name="lines[<?= salesEscape($lineKey) ?>][product_id]" aria-label="Producto" data-line-product><option value="">Selecciona un producto</option><?php foreach ($page['catalogs']['products'] as $product): ?><option value="<?= (int) $product['id'] ?>" data-price="<?= salesEscape($product['sale_price']) ?>" data-commission-type="<?= salesEscape($product['commission_type']??'none') ?>" data-commission-value="<?= salesEscape(($product['commission_type']??'none')==='fixed'?bcadd($product['commission_value']??'0','0',2):($product['commission_value']??'0')) ?>" data-currency="<?= salesEscape($product['currency_code']) ?>" data-tax="<?= (int) ($product['sale_tax_id'] ?? 0) ?>" <?= (int) ($line['product_id'] ?? 0) === (int) $product['id'] ? 'selected' : '' ?>><?= salesEscape($product['name']) ?></option><?php endforeach; ?></select></td>
    <td><input name="lines[<?= salesEscape($lineKey) ?>][quantity]" aria-label="Cantidad" inputmode="decimal" maxlength="12" value="<?= salesEscape(decimalInput($line['quantity'] ?? '1.00')) ?>" data-line-quantity></td>
    <td><input name="lines[<?= salesEscape($lineKey) ?>][unit_price]" aria-label="Precio unitario" inputmode="decimal" maxlength="13" value="<?= salesEscape($line['unit_price'] ?? '0.00') ?>" data-line-price></td>
    <td><input aria-label="Precio en tienda" readonly value="<?= salesEscape($line['commission_reference_price'] ?? '') ?>" data-line-reference placeholder="—"></td>
    <td class="quotation-money" data-line-commission><?= salesEscape($line['commission_amount'] ?? '0.00') ?></td>
    <td><select name="lines[<?= salesEscape($lineKey) ?>][tax_id]" aria-label="Impuesto" data-line-tax><option value="">Sin impuesto</option><?php foreach ($page['catalogs']['taxes'] as $tax): ?><?php $storedTax=(int)($line['tax_id']??0)===(int)$tax['id']; ?><option value="<?= (int) $tax['id'] ?>" data-rate="<?= salesEscape($storedTax && isset($line['tax_rate']) ? $line['tax_rate'] : $tax['rate']) ?>" data-tax-name="<?= salesEscape($storedTax?($line['tax_name']??$tax['name']):$tax['name']) ?>" data-catalog-rate="<?= salesEscape($tax['rate']) ?>" data-catalog-name="<?= salesEscape($tax['name']) ?>" <?= $storedTax ? 'selected' : '' ?>><?= salesEscape($storedTax?($line['tax_name']??$tax['name']):$tax['name']) ?></option><?php endforeach; ?></select></td>
    <td class="quotation-money" data-line-base><?= salesEscape($line['base_amount'] ?? '0.00') ?></td><td class="quotation-money" data-line-total><?= salesEscape($line['total_amount'] ?? '0.00') ?></td>
    <?php if (! ($locked ?? $confirmed)): ?><td class="contact-row-action"><button class="contact-button contact-icon-button" type="button" aria-label="Eliminar línea" title="Eliminar línea" data-remove-line hidden><?php require dirname(__DIR__) . '/partials/remove-icon.php'; ?></button></td><?php endif; ?>
</tr>
